#!/usr/bin/env python3
"""Generates the 256 ordered pairs asserted by p4_demand_lattice.rs.

Written out rather than sampled, because a law asserted over a subset of the shapes
it is claimed for is a choice about what not to find out.
"""
rows = []
for i in range(16):
    for j in range(16):
        a = [(i >> k) & 1 for k in range(4)]
        b = [(j >> k) & 1 for k in range(4)]
        rows.append("    %d %d %d %d | %d %d %d %d" % (*a, *b))
body = "union_is_the_join!(\n" + ",\n".join(rows) + ",\n);\n"
open("p4_pairs.inc", "w").write(
    "// generated by p4_generate_pairs.py; %d ordered pairs, the whole 16 x 16 table\n" % len(rows)
    + body)
print("wrote p4_pairs.inc with %d pairs" % len(rows))

trips = []
for i in range(16):
    for j in range(16):
        for k in range(16):
            a = [(i >> t) & 1 for t in range(4)]
            b = [(j >> t) & 1 for t in range(4)]
            c = [(k >> t) & 1 for t in range(4)]
            trips.append("    %d %d %d %d | %d %d %d %d | %d %d %d %d" % (*a, *b, *c))
open("p4_triples.inc", "w").write(
    "// generated by p4_generate_pairs.py; %d ordered triples, the whole 16^3 table\n" % len(trips)
    + "join_is_associative!(\n" + ",\n".join(trips) + ",\n);\n")
print("wrote p4_triples.inc with %d triples" % len(trips))
